import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for TokenBuffer.writeEndArray().
 */
public class TokenBuffer_writeEndArray_TriageGen0Test {

    private ObjectMapper mapper;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
    }

    /**
     * Tests that writeEndArray correctly appends the END_ARRAY token
     * and moves the write context up to the parent.
     */
    @Test
    public void testWriteEndArray_UpdatesContextAndAppendsToken() throws IOException, JsonGenerationException {
        TokenBuffer buffer = new TokenBuffer(mapper);

        // 1. Start an array to create a nested context
        buffer.writeStartArray();

        // Verify current token is START_ARRAY
        assertEquals(JsonToken.START_ARRAY, buffer.firstToken());

        // 2. Call writeEndArray
        buffer.writeEndArray();

        // 3. Verify the last token appended is END_ARRAY
        // Since we can't check the "last" token directly via public API easily without a parser, 
        // we use serialize to a generator or check via a parser.
        // A more direct way is to use the buffer to generate JSON and check content.
        String json = buffer.toString();
        assertEquals("[]", json);
    }

    /**
     * Tests the branch where _writeContext.getParent() is null.
     * This happens when we call writeEndArray at the root level without a start token.
     */
    @Test
    public void testWriteEndArray_AtRootLevel_NoParent() throws IOException, JsonGenerationException {
        TokenBuffer buffer = new TokenBuffer(mapper);

        // Call writeEndArray without calling writeStartArray first
        // This triggers the (c != null) check where c will be null
        buffer.writeEndArray();

        String json = buffer.toString();
        assertEquals("]", json);
    }

    /**
     * Tests deep nesting to ensure the context moves up correctly through multiple levels.
     */
    @Test
    public void testWriteEndArray_DeepNesting() throws IOException, JsonGenerationException {
        TokenBuffer buffer = new TokenBuffer(mapper);

        // Structure: [ [ ] ]
        buffer.writeStartArray(); // Level 1
        buffer.writeStartArray(); // Level 2
        buffer.writeEndArray();   // Close Level 2

        // After closing Level 2, the context should be back at Level 1
        // If we add a value now, it should be inside Level 1
        buffer.writeNumber(1);

        buffer.writeEndArray();   // Close Level 1

        String json = buffer.toString();
        assertEquals("[[1]]", json);
    }

    /**
     * Tests that writeEndArray works correctly when combined with objects.
     */
    @Test
    public void testWriteEndArray_WithObjectContext() throws IOException, JsonGenerationException {
        TokenBuffer buffer = new TokenBuffer(mapper);

        // Structure: {"a": []}
        buffer.writeStartObject();
        buffer.writeFieldName("a");
        buffer.writeStartArray();
        buffer.writeEndArray();
        buffer.writeEndObject();

        String json = buffer.toString();
        assertEquals("{\"a\":[]}", json);
    }
}
